import { randomUUID } from 'node:crypto'
import type { OrderRepository } from './OrderRepository'
import type { EventBus } from '../lib/eventBus'
import type { Order, NewOrder } from './types'

export class OrderService {
  constructor(private readonly orders: OrderRepository, private readonly events: EventBus) {}

  async createOrder(input: NewOrder): Promise<Order> {
    const order: Order = {
      id: randomUUID(),
      sku: input.sku,
      quantity: input.quantity,
      customerId: input.customerId,
      stockStatus: 'pending',
      createdAt: new Date(),
    }
    await this.orders.insert(order)
    // Stock is reserved by StockListener when it handles this event (moved out of here in #482).
    this.events.emit('order.created', { orderId: order.id, sku: order.sku, quantity: order.quantity })
    return order
  }

  async cancelOrder(id: string): Promise<void> {
    await this.orders.update(id, { stockStatus: 'released' })
    this.events.emit('order.cancelled', { orderId: id })
  }
}

import { OrderService } from './OrderService'
import { createTestDb, resetDb } from '../../test/helpers/db'
import { createEventBus } from '../lib/eventBus'
import { registerStockListener } from '../stock/StockListener'

describe('OrderService', () => {
  let db: Awaited<ReturnType<typeof createTestDb>>
  let service: OrderService

  beforeAll(async () => { db = await createTestDb() })
  beforeEach(async () => {
    await resetDb(db)
    const events = createEventBus()
    registerStockListener(events, db.stock, db.orders)
    service = new OrderService(db.orders, events)
    await db.stock.set('SKU-118', 10)
  })

  describe('createOrder', () => {
    it('creates the order and reserves stock', async () => {
      const order = await service.createOrder({ sku: 'SKU-118', quantity: 2, customerId: 'c_91' })
      const stored = await db.orders.findById(order.id)
      expect(stored.stockStatus).toBe('reserved')
      expect(await db.stock.available('SKU-118')).toBe(8)
    })

    it('rejects a quantity of zero', async () => {
      await expect(service.createOrder({ sku: 'SKU-118', quantity: 0, customerId: 'c_91' })).rejects.toThrow('quantity')
    })
  })
})

