import type { EventBus } from '../lib/eventBus'
import type { StockRepository } from './StockRepository'
import type { OrderRepository } from '../orders/OrderRepository'

export function registerStockListener(events: EventBus, stock: StockRepository, orders: OrderRepository) {
  // Reserves stock for a new order. Runs after createOrder() has already returned.
  events.on('order.created', async ({ orderId, sku, quantity }) => {
    await stock.decrement(sku, quantity)
    await orders.update(orderId, { stockStatus: 'reserved' })
    events.emit('stock.reserved', { orderId })
  })
}

const COLORS: Record<string, string> = {
  pending: 'bg-amber-100 text-amber-800',
  reserved: 'bg-sky-100 text-sky-800',
  shipped: 'bg-emerald-100 text-emerald-800',
  released: 'bg-slate-100 text-slate-600',
}

export function OrderStatusBadge({ status }: { status: string }) {
  // Orders show as "pending" until stock is reserved, then "reserved".
  return <span className={`rounded px-2 py-0.5 text-xs ${COLORS[status] ?? COLORS.pending}`}>{status}</span>
}

