type Handler = (payload: any) => unknown

export type EventBus = ReturnType<typeof createEventBus>

export function createEventBus() {
  const handlers = new Map<string, Handler[]>()
  return {
    on(event: string, handler: Handler) {
      handlers.set(event, [...(handlers.get(event) ?? []), handler])
    },
    // Fire-and-forget: handlers run on their own; emit() never waits for them or sees their errors.
    emit(event: string, payload: unknown) {
      for (const handler of handlers.get(event) ?? []) void Promise.resolve().then(() => handler(payload))
    },
  }
}

import type { EventBus } from '../../src/lib/eventBus'

export function waitForEvent(events: EventBus, name: string, timeoutMs = 2000): Promise<unknown> {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error(`timed out waiting for ${name}`)), timeoutMs)
    // Register before the caller triggers the event, or a fast handler can fire first.
    events.on(name, (payload) => { clearTimeout(timer); resolve(payload) })
  })
}

export async function refundOrder(orderId: string, reason: string) {
  const payment = await payments.findByOrder(orderId)
  if (!payment) throw new NotFoundError(`no payment for order ${orderId}`)
  const refund = await psp.refund(payment.pspId, { amount: payment.amount, reason })
  await payments.update(payment.id, { status: 'refunded', refundId: refund.id })
  return refund
}
